sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {

    if (isLoading || !newValue)
        return;

    var ga = new GlideAjax('VendorAjaxUtils');

    ga.addParam(
        'sysparm_name',
        'isDuplicateTaxId'
    );

    ga.addParam(
        'sysparm_taxid',
        newValue
    );

    ga.getXMLAnswer(function(answer) {

        if (answer == 'true') {

            g_form.showFieldMsg(
                'tax_id',
                'Duplicate Tax ID exists.',
                'error'
            );

            g_form.clearValue('tax_id');
        }
    });
}
